SgAutocomplete<String>(
  id: 'cidade',
  labelText: context.tx('Cidade'),
  delay: 200,
  loadingText: context.tx('Buscando cidades...'),
  source: (q) async {
    await Future<void>.delayed(const Duration(milliseconds: 600));
