Builder(
  builder: (context) {
    final width = MediaQuery.sizeOf(context).width;
    final visible = width >= 1024 ? 4 : (width >= 768 ? 2 : 1);
    return SizedBox(
      height: 256,
      child: SgCarousel(
        key: ValueKey(visible),
        items: _slides(),
        numVisible: visible,
        numScroll: visible == 4 ? 2 : 1,
        orientation: SgCarouselOrientation.horizontal,
        height: '100%',
      ),
    );
  },
)

