            SgFadeDigit(value: horas[0]),
            SgFadeDigit(value: horas[1]),
            const Text(
              ':',
              style: TextStyle(
                fontSize: 36,
                fontWeight: FontWeight.bold,
              ),
            ),
            SgFadeDigit(value: minutos[0]),
            SgFadeDigit(value: minutos[1]),
            const Text(
              ':',
              style: TextStyle(
                fontSize: 36,
